  'user.login.infos': "NEXTPlutus est un outil auxiliaire d'analyse boursière multi-agents d'IA et n'a pas de qualifications en conseil en investissement en valeurs mobilières. Tous les résultats d'analyse, scores et avis de référence de la plateforme sont automatiquement générés par l'IA sur la base de données historiques et sont utilisés uniquement à des fins d'apprentissage, de recherche et d'échange technique, et ne constituent aucun conseil d'investissement ou base de prise de décision. L'investissement en actions implique divers risques tels que le risque de marché, le risque de liquidité, le risque politique, etc., qui peuvent entraîner une perte du principal. Les utilisateurs doivent prendre des décisions indépendantes en fonction de leur propre tolérance au risque, et tout comportement d'investissement et conséquences découlant de l'utilisation de cet outil seront à la charge de l'utilisateur. Le marché est risqué et les investissements doivent être prudents.",
