  'user.login.legal.required': "Veuillez d'abord lire et vérifier les mentions légales",
  'user.login.legal.content': "NEXTPlutus est un outil auxiliaire d'analyse boursière multi-agents d'IA et n'a pas de qualifications en conseil en investissement en valeurs mobilières. Tous les résultats d'analyse, notes et avis de référence de la plateforme sont automatiquement générés par l'IA sur la base de données historiques et sont utilisés uniquement à des fins d'apprentissage, de recherche et d'échange technique, et ne constituent aucun conseil d'investissement ou base de prise de décision. L'investissement en actions implique divers risques tels que le risque de marché, le risque de liquidité, le risque politique, etc., qui peuvent entraîner une perte du principal. Les utilisateurs doivent prendre des décisions indépendantes en fonction de leur propre tolérance au risque, et tout comportement d'investissement et conséquences découlant de l'utilisation de cet outil seront à la charge de l'utilisateur. Le marché est risqué et les investissements doivent être prudents.",
  'user.login.privacy.title': 'Politique de confidentialité des utilisateurs',
  'user.login.privacy.view': 'Afficher la politique de confidentialité des utilisateurs',
  'user.login.privacy.collapse': 'Fermer les conditions de confidentialité des utilisateurs',
  'user.login.privacy.content': "Nous accordons une grande importance à votre vie privée et à la protection de vos données. 1) Portée de la collecte : seules les informations nécessaires à la mise en œuvre de la fonction (telles que l'e-mail, le numéro de téléphone mobile, l'indicatif régional, l'adresse du portefeuille Web3) ainsi que les journaux et informations sur l'appareil nécessaires sont collectés. 2) Objectif d'utilisation : Pour la connexion au compte et la vérification de la sécurité, la fourniture de fonctions de service, le dépannage et les exigences de conformité. 3) Stockage et sécurité : les données sont cryptées et stockées, et les autorisations et mesures de contrôle d'accès nécessaires sont prises pour tenter d'empêcher tout accès non autorisé, toute divulgation ou toute perte. 4) Partage avec des tiers : sauf si les lois et réglementations l'exigent ou si cela est nécessaire à l'exécution des services, vos informations personnelles ne seront pas partagées avec des tiers ; si des services tiers (tels que des portefeuilles, des fournisseurs de services SMS) sont impliqués, ils ne seront traités que dans la mesure minimale nécessaire à la mise en œuvre de la fonction. 5) Cookies/stockage local : utilisés pour le statut de connexion et la maintenance de session nécessaire (tels que les jetons, PHPSESSID), vous pouvez les effacer ou les restreindre dans le navigateur. 6) Droits personnels : Vous pouvez exercer vos droits d'information, de rectification, de suppression, de retrait de consentement, etc. conformément aux lois et règlements. 7) Modifications et avis : lorsque ces conditions seront mises à jour, elles seront affichées bien en évidence sur la page. En continuant à utiliser ce service, vous êtes réputé avoir lu et accepté le contenu mis à jour. Si vous n'acceptez pas ces Conditions ou toute mise à jour de celles-ci, veuillez cesser d'utiliser le Service et nous contacter.",
  'user.login.legal.agreeButton': 'Accepter',
  
