  "dashboard.indicator.backtest.executionAssumptions.bodyAggressive1m": "Agressif (crypto) : signaux sur la même barre selon la stratégie TF {sig}, intégrés aux barres {exec} (interrogation en direct ≈10 s). Les ordres SL/TP peuvent être déclenchés plus tôt sur les sous-barres.",
  "dashboard.indicator.backtest.executionAssumptions.bodyAggressiveBar": "Agressif : confirmation et exécution de la même transaction (avec glissement). Généralement plus optimiste que le mode strict.",
