  "dashboard.indicator.backtest.executionAssumptions.bodySameBar": "Une fois le signal confirmé à la clôture d'une barre, les ordres sont exécutés en utilisant le cours de clôture de cette barre (plus le glissement). Les horodatages correspondent aux marqueurs du graphique ; les résultats sont généralement plus optimistes.",
  "dashboard.indicator.backtest.executionAssumptions.bodyScriptStandard": "Test de stratégie par script : la fonction `on_bar` s'exécute sur chaque barre fermée de l'unité de temps de la stratégie ; les ordres du script sont exécutés par défaut à l'ouverture de la barre suivante (avec slippage et frais). Il ne s'agit pas de l'option permettant de basculer entre le mode strict et non strict de l'indicateur, mais du chemin de relecture standard du script.",
  "dashboard.indicator.backtest.executionAssumptions.bodyStrict": "Mode strict : signaux uniquement sur les barres fermées, exécutés à l’ouverture de la barre suivante (avec glissement). Correspond au mode strict en direct : conservateur mais plus réaliste.",
