  "dashboard.indicator.guide.intro": "Cette plateforme permet de créer des indicateurs techniques et des signaux de trading personnalisés en Python. Le système intègre les bibliothèques d'analyse de données pandas et numpy. Vous pouvez utiliser les opérations standard sur les DataFrames pour traiter les données K-line, tracer des graphiques ou marquer des signaux d'achat/vente.",
  "dashboard.indicator.guide.section1.data": "Données d'entrée : df",
  "dashboard.indicator.guide.section1.dataColumns": "<code>df</code> contient les colonnes suivantes (toutes de type float) :",
  "dashboard.indicator.guide.section1.dataColumnsList": "<code>time</code> (horodatage, secondes), <code>open</code>, <code>high</code>, <code>low</code>, <code>close</code>, <code>volume</code>",
  "dashboard.indicator.guide.section1.dataDesc": "Le système convertit automatiquement les données K-line actuelles en un objet Pandas DataFrame, le nom de la variable est <code>df</code>.",
  "dashboard.indicator.guide.section1.dataIndex": "Important : l’index df est un horodatage (DatetimeIndex), veuillez le préserver et éviter d’utiliser <code>.values</code> qui entraîne la perte de l’index.",
  "dashboard.indicator.guide.section1.dataNote": "L'index des données est organisé des plus anciennes aux plus récentes (0 correspond aux données les plus anciennes, la dernière ligne aux données les plus récentes).",
  "dashboard.indicator.guide.section1.env": "Votre code s'exécute dans un environnement Python basé sur un navigateur (Pyodide).",
  "dashboard.indicator.guide.section1.libs": "Bibliothèques préinstallées",
  "dashboard.indicator.guide.section1.libsDesc": "Les bibliothèques suivantes sont importées par défaut, il n'est pas nécessaire de les importer à nouveau :",
  "dashboard.indicator.guide.section1.libsList": "<code>pandas</code> (pd), <code>numpy</code> (np), <code>math</code>, <code>json</code>",
  "dashboard.indicator.guide.section1.title": "1. Environnement d'exécution et variables prédéfinies",
  "dashboard.indicator.guide.section2.desc": "Vous pouvez définir des variables comme paramètres au début de votre code. Le système tentera d'interpréter les instructions telles que `<code>variable = value</code>` comme des paramètres ajustables.",
  "dashboard.indicator.guide.section2.example": "Exemple de paramètre",
  "dashboard.indicator.guide.section2.exampleCode": "<code>span = 20</code> ou <code>multiplier = 2.0</code>",
  "dashboard.indicator.guide.section2.title": "2. Définition des paramètres",
  "dashboard.indicator.guide.section3.backtestBuySignal": "<code>df['buy_signal']</code> - Série booléenne, Vrai indique un signal d'achat",
  "dashboard.indicator.guide.section3.backtestExample": "Example:",
  "dashboard.indicator.guide.section3.backtestExampleCode": "<code>df['buy_signal'] = condition_buy</code><br/><code>df['sell_signal'] = condition_sell</code>",
  "dashboard.indicator.guide.section3.backtestNote": "Remarque : même si vous ne définissez que <code>output.signals</code> pour l’affichage du graphique, vous devez définir ces deux colonnes pour activer le backtesting.",
  "dashboard.indicator.guide.section3.backtestRequired": "<strong>Requis pour le backtesting :</strong>",
  "dashboard.indicator.guide.section3.backtestSellSignal": "<code>df['sell_signal']</code> - Série booléenne, Vrai indique un signal de vente",
  "dashboard.indicator.guide.section3.desc": "Si vous souhaitez que votre indicateur prenne en charge le backtesting, vous devez définir les deux colonnes suivantes dans votre code :",
  "dashboard.indicator.guide.section3.title": "3. Configuration du signal de backtest (Important !)",
  "dashboard.indicator.guide.section4.calculatedVars": "<code>calculatedVars</code> - Variables calculées (facultatif, pour afficher des informations supplémentaires)",
  "dashboard.indicator.guide.section4.desc": "À la fin de l'exécution du code, vous devez définir un dictionnaire nommé <code>output</code> pour indiquer au graphique comment afficher les résultats.",
  "dashboard.indicator.guide.section4.fields": "Le dictionnaire <code>output</code> contient les champs suivants :",
  "dashboard.indicator.guide.section4.name": "<code>nom</code> - Nom de l'indicateur (facultatif)",
