  "dashboard.indicator.guide.section5.table.color": "Couleur de la ligne (format hexadécimal, par exemple « #ff0000 »). Si ce champ n'est pas renseigné, le système attribuera automatiquement une couleur.",
  "dashboard.indicator.guide.section5.table.data": "La longueur de la liste de données doit correspondre au nombre de lignes du dataframe. Il est recommandé d'utiliser <code>series.tolist()</code>",
