  "dashboard.indicator.guide.section6.calc": "Calculer",
  "dashboard.indicator.guide.section6.desc": "Les signaux <code> et </code> servent à marquer les points d'achat/vente sur des lignes K spécifiques à l'aide d'icônes ou de texte. Remarque : <strong> Ceci est uniquement destiné à l'affichage graphique. Le système de backtest utilise <code>df['buy_signal'] et </code> et <code>df['sell_signal'] (QD_TOKEN_7__).",
  "dashboard.indicator.guide.section6.example": "Exemple : Tracer des signaux d'achat/vente",
  "dashboard.indicator.guide.section6.exampleInit": "Initialiser la liste des signaux, les remplir tous avec None",
  "dashboard.indicator.guide.section6.exampleLogic": "Logique simple : acheter lorsque le prix de clôture est supérieur au prix d’ouverture.",
  "dashboard.indicator.guide.section6.exampleNote": "En pratique, veuillez utiliser des boucles ou des opérations vectorisées.",
  "dashboard.indicator.guide.section6.examplePrice": "Prix record",
