  "fastAnalysis.indicatorsProBadge": "PRO",
  "fastAnalysis.indicatorsProSubtitle": "Alignement avec le backend `MarketDataCollector._calculate_indicators` (style standard) : le RSI(14) est lissé par la méthode de Wilder. Le MACD(12,26,9) utilise des EMA amorcées par la SMA sur les cours de clôture ; le DIF est calculé à partir de la barre 26 ; le DEA correspond à l’EMA9 de la série DIF (environ 34 barres pour une ligne de signal complète). Les MA sont des SMA. Le pivot utilise le plus haut, le plus bas et le plus bas de la barre précédente. Le swing correspond aux extrêmes haut/bas sur 20 barres. Les bandes de Bollinger sont égales à la SMA(20) ± 2 × écart-type de la population ; les niveaux agrégés utilisent BB_upper/BB_lower. L’ATR(14) est lissé par la méthode de Wilder et chaîné à la dernière barre. Consultez le fichier docs/INDICATOR_DEFINITIONS_CN.md pour le ratio de volume et la position dans la plage.",
