  "user.login.forgotPassword": "Mot de passe oublié ?",
  "user.login.infos": "QuantDinger est un outil d'analyse boursière multi-agents basé sur l'IA. Il ne constitue en aucun cas un conseil en investissement. L'ensemble des résultats d'analyse, scores et opinions de référence affichés sur la plateforme sont générés automatiquement par l'IA à partir de données historiques et sont destinés exclusivement à l'apprentissage, à la recherche et à l'analyse technique. Ils ne sauraient en aucun cas constituer un conseil en investissement ni servir de base à la prise de décision. Investir en actions comporte des risques de marché, de liquidité, de politique monétaire et autres, pouvant entraîner des pertes en capital. Il est de la responsabilité de chaque utilisateur de prendre ses propres décisions en fonction de sa tolérance au risque et d'assumer les conséquences de ses investissements réalisés à l'aide de cet outil. La prudence est de mise en matière d'investissement.",
  "user.login.legal.agree": "J'ai lu et j'accepte la clause de non-responsabilité légale.",
  "user.login.legal.collapse": "Masquer les mentions légales",
  "user.login.legal.content": "QuantDinger est un outil d'analyse boursière multi-agents basé sur l'IA et ne fournit aucun conseil en investissement. L'ensemble des résultats d'analyse, scores et références sont générés par l'IA à partir de données historiques et sont destinés exclusivement à l'apprentissage, à la recherche et à l'analyse technique. Ils ne constituent en aucun cas un conseil en investissement ni un fondement pour la prise de décision. Investir en actions comporte des risques de marché, de liquidité et de politique, pouvant entraîner une perte en capital. Il appartient à chaque utilisateur de prendre ses propres décisions en fonction de sa tolérance au risque et d'assumer les conséquences de ses investissements réalisés à l'aide de cet outil.",
