  "user.login.privacy.collapse": "Masquer la politique de confidentialité",
  "user.login.privacy.content": "Nous attachons une grande importance à la protection de votre vie privée et de vos données. (1) Collecte des données : Nous collectons uniquement les informations nécessaires à la fourniture du service (par exemple, adresse e-mail, numéro de téléphone mobile, indicatif pays, adresse du portefeuille Web3) et certaines données de connexion/appareil. (2) Finalité du traitement : Connexion au compte et vérification de sécurité, activation des fonctionnalités, dépannage et conformité réglementaire. (3) Stockage et sécurité : Les données sont chiffrées et leur accès est contrôlé afin d'empêcher tout accès, divulgation ou perte non autorisés. (4) Partage et tiers : Nous ne partageons pas vos données personnelles avec des tiers, sauf si la loi l'exige ou pour la fourniture du service. Lorsque des services tiers sont impliqués (par exemple, portefeuilles électroniques, fournisseurs de SMS), le traitement est limité au strict minimum nécessaire. (5) Cookies/stockage local : Utilisés pour la session et l'état de connexion (par exemple, jetons, PHPSESSID). Vous pouvez les supprimer ou les limiter dans votre navigateur. (6) Vos droits : Vous pouvez exercer vos droits d'accès, de rectification, d'effacement et de retrait du consentement, conformément à la loi. (7) Modifications et notifications : Nous vous informerons des mises à jour de manière visible. En continuant à utiliser ce service, vous reconnaissez avoir lu et accepté les nouvelles conditions. Si vous n'êtes pas d'accord, veuillez cesser de l'utiliser et nous contacter.",
  "user.login.privacy.title": "politique de confidentialité",
